function bhranti_plugin_restore_option( $name, $raw ) { global $wpdb; if ( null === $raw ) { $wpdb->delete( $wpdb->options, array( 'option_name' => $name ), array( '%s' ) ); } elseif ( null === bhranti_plugin_raw_option( $name ) ) { $wpdb->insert( $wpdb->options, array_merge( array( 'option_name' => $name ), $raw ), array( '%s', '%s', '%s' ) ); } else { $wpdb->update( $wpdb->options, $raw, array( 'option_name' => $name ), array( '%s', '%s' ), array( '%s' ) ); } wp_cache_delete( $name, 'options' ); wp_cache_delete( 'alloptions', 'options' ); wp_cache_delete( 'notoptions', 'options' ); }
