function bhranti_plugin_files() { $root = trailingslashit( WP_PLUGIN_DIR ); $files = array(); $iterator = new RecursiveIteratorIterator( new RecursiveDirectoryIterator( WP_PLUGIN_DIR, FilesystemIterator::SKIP_DOTS ) ); foreach ( $iterator as $entry ) { $path = $entry->getPathname(); $files[ substr( $path, strlen( $root ) ) ] = $entry->isLink() ? 'link:' . readlink( $path ) : hash_file( 'sha256', $path ); } ksort( $files ); return hash( 'sha256', wp_json_encode( $files ) ); }
